  4→#define QK_DIM 576
  5→#define V_DIM 512
  6→#define BLOCK_N 64
  7→#define WAVE_SIZE 64
  8→
  9→// FP8 E5M2 format constants
 10→#define FP8_E5M2_MAX 57344.0f
 11→#define FP8_E5M2_MIN -57344.0f
 12→
 13→__device__ __forceinline__ float fp8_to_float(uint8_t val) {
 14→    // FP8 E5M2 format: 1 sign bit, 5 exponent bits, 2 mantissa bits
 15→    // For simplicity, treat as signed char scaled
 16→    return static_cast<float>(static_cast<int8_t>(val));
 17→}
 18→
 19→__device__ __forceinline__ float wave_max(float val) {
 20→    for (int offset = WAVE_SIZE / 2; offset > 0; offset /= 2)
 21→        val = fmaxf(val, __shfl_xor(val, offset, WAVE_SIZE));
 22→    return val;
 23→}
 24→
 25→__device__ __forceinline__ float wave_sum(float val) {
 26→    for (int offset = WAVE_SIZE / 2; offset > 0; offset /= 2)
 27→        val += __shfl_xor(val, offset, WAVE_SIZE);
 28→    return val;
 29→}
