 31→// Fused MLA Decode: FP8 input format (matches AITER)
 32→__global__ void mla_top10_kernel(
 33→    const __hip_bfloat16* __restrict__ Q,      // [bs, nh, 576] - bfloat16 query
 34→    const uint8_t* __restrict__ KV,          // [bs, sl, 576] - FP8 KV cache
 35→    __hip_bfloat16* __restrict__ O,            // [bs, nh, 512] - bfloat16 output
 36→    int bs, int sl, int nh, float sc) 
 37→{
 38→    int hi = blockIdx.x, bi = blockIdx.y, tid = threadIdx.x;
 39→    const __hip_bfloat16* qp = Q + (bi * nh + hi) * QK_DIM;
 40→    const uint8_t* kvp = KV + bi * sl * QK_DIM;  // [sl, 576] FP8
 41→    __hip_bfloat16* op = O + (bi * nh + hi) * V_DIM;
 42→
 43→    // Load Q into shared memory
 44→    __shared__ float sq[QK_DIM];
 45→    for (int i = tid; i < QK_DIM; i += blockDim.x) 
 46→        sq[i] = __bfloat162float(qp[i]);
 47→    __syncthreads();
 48→
 49→    float running_max = -1e30f, running_sum = 0.0f;
 50→    float local_v[8] = {0.0f};  // V_DIM 512 / 64 threads = 8 elements per thread
 51→
 52→    for (int k = 0; k < sl; k += BLOCK_N) {
 53→        int remain = sl - k;
 54→        int current_n = (remain < BLOCK_N) ? remain : BLOCK_N;
 55→
 56→        // QK Dot Product
 57→        float score = -1e30f;
 58→        if (tid < current_n) {
 59→            const uint8_t* kf = kvp + (k + tid) * QK_DIM;  // [576] FP8
 60→            float acc = 0.0f;
 61→            
 62→            // Unrolled dot product
 63→            for (int i = 0; i < QK_DIM; i++) {
 64→                acc += sq[i] * fp8_to_float(kf[i]);
 65→            }
 66→            score = acc * sc;
 67→        }
 68→
 69→        // Online Softmax
 70→        float block_max = wave_max(score);
 71→        float old_max = running_max;
 72→        running_max = fmaxf(old_max, block_max);
 73→        
 74→        float p = expf(score - running_max);
 75→        float correction = expf(old_max - running_max);
 76→        
 77→        running_sum = running_sum * correction + wave_sum(tid < current_n ? p : 0.0f);
 78→
 79→        // V Accumulation
 80→        for (int i = 0; i < 8; i++) {
 81→            int v_dim_idx = tid + i * 64;
 82→            local_v[i] *= correction;
 83→            
 84→            for (int j = 0; j < current_n; j++) {
 85→                float weight = __shfl(p, j, WAVE_SIZE);
 86→                const uint8_t* kv_j = kvp + (k + j) * QK_DIM;
 87→                float v_val = fp8_to_float(kv_j[v_dim_idx]);
 88→                local_v[i] += weight * v_val;
 89→            }
 90→        }
 91→    }
 92→
 93→    // Finalize
 94→    float inv_sum = 1.0f / running_sum;
 95→    for (int i = 0; i < 8; i++) {
 96→        int v_dim_idx = tid + i * 64;
 97→        if (v_dim_idx < V_DIM) {
 98→            op[v_dim_idx] = __float2bfloat16(local_v[i] * inv_sum);
 99→        }
100→    }
101→}
