104→    void* Q, void* KV, void* O,
105→    int bs, int sl, int nh, float sc) 
106→{
107→    dim3 grid(nh, bs), block(64);
108→    hipLaunchKernelGGL(mla_top10_kernel, grid, block, 0, 0,
109→        (const __hip_bfloat16*)Q, (const uint8_t*)KV, (__hip_bfloat16*)O,
110→        bs, sl, nh, sc);
111→    return 0;
