 15→#include <hip/hip_runtime.h>
 16→#include <hip/hip_bfloat16.h>
 17→#include <stdint.h>
 18→#include <math.h>
 19→
 20→// ─── Architecture Constants ───────────────────────────────────────────────────
 21→constexpr int WARP_SIZE = 64;
 22→constexpr int NUM_THREADS = 512;
 23→constexpr float FP4_MAX = 6.0f;
 24→
 25→// ─── Dynamic Tile Selection ───────────────────────────────────────────────────
 26→__device__ __forceinline__ int get_block_m(int M, int N, int K) {
 27→    if (M <= 16) return 64;
 28→    if (M <= 64) return 128;
 29→    return 256;
 30→}
 31→
 32→__device__ __forceinline__ int get_block_n(int M, int N, int K) {
 33→    if (N <= 1024) return 64;
 34→    if (N <= 2048) return 128;
 35→    return 256;
 36→}
 37→
 38→__device__ __forceinline__ int get_block_k(int K) {
 39→    return (K >= 2048) ? 256 : 128;
 40→}
