 42→// ─── 128-bit Vector Types ─────────────────────────────────────────────────────
 43→using u32x4 = uint32_t __attribute__((ext_vector_type(4)));
 44→using as3_uint32_ptr = uint32_t __attribute__((address_space(3))) *;
 45→
 46→// ─── LLVM Intrinsics ──────────────────────────────────────────────────────────
 47→extern "C" __device__ void llvm_amdgcn_raw_buffer_load_lds(
 48→    u32x4 rsrc,
 49→    as3_uint32_ptr lds_ptr,
 50→    int size,
 51→    int voffset,
 52→    int soffset,
 53→    int offset,
 54→    int aux
 55→) __asm("llvm.amdgcn.raw.buffer.load.lds");
 56→
 57→__device__ __forceinline__ u32x4 make_srsrc(const void* ptr, uint32_t range_bytes) {
 58→    struct buffer_resource {
 59→        uint64_t ptr;
 60→        uint32_t range;
 61→        uint32_t config;
 62→    };
 63→    buffer_resource rsrc = {
 64→        reinterpret_cast<uint64_t>(ptr),
 65→        range_bytes,
 66→        0x110000  // GFX950
 67→    };
 68→    return *reinterpret_cast<const u32x4*>(&rsrc);
 69→}
