 71→// ─── FP4 Quantization (IEEE 754 round-to-nearest) ─────────────────────────────
 72→__device__ __forceinline__ void quantize_bf16_to_fp4(
 73→    hip_bfloat16 val,
 74→    uint8_t& scale_exp,
 75→    uint8_t& fp4_val
 76→) {
 77→    float f = __bfloat162float(val);
 78→    float abs_f = fabsf(f);
 79→    
 80→    if (abs_f > 0.0f) {
 81→        uint32_t bits = __float_as_uint(abs_f);
 82→        uint32_t rounded = (bits + 0x200000u) & 0xFF800000u;
 83→        int exp_biased = (rounded >> 23) & 0xFF;
 84→        scale_exp = exp_biased - 2;
 85→        
 86→        float quant_scale = exp2f(129.0f - (float)scale_exp);
 87→        float qx = abs_f * quant_scale;
 88→        
 89→        if (qx >= FP4_MAX) {
 90→            fp4_val = 0x7;
 91→        } else if (qx < 1.0f) {
 92→            fp4_val = (uint8_t)(qx * 8.0f);
 93→        } else {
 94→            fp4_val = (uint8_t)qx;
 95→        }
 96→        
 97→        if (f < 0.0f) {
 98→            fp4_val |= 0x8;
 99→        }
100→    } else {
101→        scale_exp = 0;
102→        fp4_val = 0;
103→    }
104→}
