106→// ─── LDS Swizzle (XOR for 64 banks) ───────────────────────────────────────────
107→__device__ __forceinline__ int swizzle_col(int row, int col) {
108→    const int pair = (row >> 1) & 7;
109→    const int perm = pair ^ (((pair >> 1) ^ (pair >> 2)) & 1);
110→    const int mask = perm << 4;
111→    return col ^ mask;
112→}
