114→// ─── Scheduling Intrinsics ────────────────────────────────────────────────────
115→__device__ __forceinline__ void wave_barrier() {
116→    __builtin_amdgcn_s_barrier();
117→}
118→
119→__device__ __forceinline__ void set_priority(int prio) {
120→    __builtin_amdgcn_s_setprio(prio);
121→}
122→
123→__device__ __forceinline__ void sched_barrier(int mask) {
124→    __builtin_amdgcn_sched_barrier(mask);
125→}
