127→__device__ __forceinline__ float unpack_fp4(uint8_t val) {
128→    float sign = ((val >> 3) & 0x1) ? -1.0f : 1.0f;
129→    float exp = (val >> 2) & 0x1;
130→    float mant = val & 0x3;
131→    return exp ? sign * (1.0f + mant * 0.5f) : sign * mant * 0.125f;
132→}
