134→// ─── Combined Kernel (All Optimizations) ──────────────────────────────────────
135→__global__ __launch_bounds__(NUM_THREADS, 1)
136→void fused_mxfp4_gemm_final(
137→    const hip_bfloat16* A,
138→    const uint8_t* B_fp4,
139→    const uint8_t* B_scale,
140→    hip_bfloat16* C,
141→    int M, int N, int K
142→) {
143→    // Dynamic tile selection
144→    const int BLOCK_M = get_block_m(M, N, K);
145→    const int BLOCK_N = get_block_n(M, N, K);
146→    const int BLOCK_K = get_block_k(K);
147→    
148→    __shared__ uint8_t lds_A[2][BLOCK_M * BLOCK_K];
149→    __shared__ uint8_t lds_B[BLOCK_N * BLOCK_K];
150→    __shared__ float acc[BLOCK_M * BLOCK_N];
151→    
152→    const int tid = threadIdx.x;
153→    const int wave_id = tid / WARP_SIZE;
154→    const int lane_id = tid % WARP_SIZE;
155→    const int wave_m = wave_id / 4;
156→    const int wave_n = wave_id % 4;
157→    
158→    const int m_start = blockIdx.y * BLOCK_M;
159→    const int n_start = blockIdx.x * BLOCK_N;
160→    
161→    // Init accumulator
162→    for (int i = tid; i < BLOCK_M * BLOCK_N; i += NUM_THREADS) {
163→        acc[i] = 0.0f;
164→    }
165→    __syncthreads();
166→    
167→    // Source resources for direct LDS
168→    u32x4 a_srsrc = make_srsrc(A + m_start * K, M * K * sizeof(hip_bfloat16));
169→    u32x4 b_srsrc = make_srsrc(B_fp4 + n_start * (K/2), N * (K/2));
170→    
171→    int tic = 0;
172→    
173→    for (int k0 = 0; k0 < K; k0 += BLOCK_K) {
174→        // Memory waves: Direct global→LDS (128-bit)
175→        if (wave_id < 4) {
176→            llvm_amdgcn_raw_buffer_load_lds(
177→                a_srsrc,
178→                reinterpret_cast<as3_uint32_ptr>(lds_A[tic]),
179→                16,
180→                lane_id * 4,
181→                0, 0, 0
182→            );
183→            
184→            llvm_amdgcn_raw_buffer_load_lds(
185→                b_srsrc,
186→                reinterpret_cast<as3_uint32_ptr>(lds_B),
187→                16,
188→                lane_id * 4,
189→                0, 0, 0
190→            );
191→        }
192→        
193→        __syncthreads();
194→        
195→        // Compute waves: MFMA with swizzle
196→        if (wave_id >= 4) {
197→            float c_frag[4] = {0};
198→            set_priority(1);
199→            
200→            for (int k_frag = 0; k_frag < BLOCK_K / 128; k_frag++) {
201→                int a_row = wave_m * 16 + lane_id;
202→                int a_col = k_frag * 128;
203→                int swizzled_a = swizzle_col(a_row, a_col);
204→                uint8_t a_val = lds_A[tic][a_row * BLOCK_K + swizzled_a];
205→                
206→                int b_row = wave_n * 16 + lane_id;
207→                int b_col = k_frag * 128;
208→                int swizzled_b = swizzle_col(b_row, b_col);
209→                uint8_t b_val = lds_B[b_row * BLOCK_K + swizzled_b];
210→                
211→                c_frag[0] += unpack_fp4(a_val) * unpack_fp4(b_val);
212→                wave_barrier();
213→            }
214→            
215→            set_priority(0);
216→            
217→            for (int i = 0; i < 4; i++) {
218→                int m_out = m_start + (wave_m * 16) + (i * 4);
219→                int n_out = n_start + (wave_n * 16) + lane_id;
220→                if (m_out < M && n_out < N) {
221→                    atomicAdd(&acc[(m_out - m_start) * BLOCK_N + (n_out - n_start)], c_frag[i]);
222→                }
223→            }
224→        }
225→        
226→        tic ^= 1;
227→        sched_barrier(0);
228→        wave_barrier();
229→    }
230→    
231→    // Write output
232→    for (int i = tid; i < BLOCK_M * BLOCK_N; i += NUM_THREADS) {
233→        int m_out = m_start + (i / BLOCK_N);
234→        int n_out = n_start + (i % BLOCK_N);
235→        if (m_out < M && n_out < N) {
236→            C[m_out * N + n_out] = __float2bfloat16(acc[i]);
237→        }
238→    }
239→}
